<?php require_once __DIR__.'/../shared/config.php';require_admin();$from=$_GET['from']??'2000-01-01';$to=$_GET['to']??date('Y-m-d');$q=db()->prepare('SELECT payment_ref,patient_name,patient_phone,service_name,amount,payment_datetime,status,recorded_by_name FROM payments WHERE DATE(payment_datetime) BETWEEN ? AND ? ORDER BY payment_datetime DESC');$q->execute([$from,$to]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="dental-payments-'.$from.'-to-'.$to.'.csv"');$out=fopen('php://output','w');fputcsv($out,['Reference','Patient','Mobile','Service','Amount','Payment Date & Time','Status','Recorded By']);while($row=$q->fetch(PDO::FETCH_ASSOC))fputcsv($out,$row);fclose($out);exit;
